Here are comprehensive unit tests for the `zip_dicts` function using pytest style, covering happy path, edge cases, and error cases:

```python
import pytest

def test_zip_dicts_happy_path():
    """Test basic functionality with multiple dictionaries."""
    dict1 = {'a': 1, 'b': 2}
    dict2 = {'a': 10, 'c': 30}
    dict3 = {'b': 200, 'd': 400}

    result = zip_dicts(dict1, dict2, dict3)

    expected = {
        'a': [1, 10, None],
        'b': [2, None, 200],
        'c': [None, 30, None],
        'd': [None, None, 400]
    }
    assert result == expected

def test_zip_dicts_single_dict():
    """Test with a single dictionary."""
    dict1 = {'a': 1, 'b': 2}

    result = zip_dicts(dict1)

    expected = {
        'a': [1],
        'b': [2]
    }
    assert result == expected

def test_zip_dicts_empty_dicts():
    """Test with empty dictionaries."""
    dict1 = {}
    dict2 = {}

    result = zip_dicts(dict1, dict2)

    assert result == {}

def test_zip_dicts_mixed_empty_dicts():
    """Test with some empty dictionaries."""
    dict1 = {'a': 1}
    dict2 = {}
    dict3 = {'b': 2}

    result = zip_dicts(dict1, dict2, dict3)

    expected = {
        'a': [1, None, None],
        'b': [None, None, 2]
    }
    assert result == expected

def test_zip_dicts_no_dicts():
    """Test with no dictionaries provided."""
    result = zip_dicts()

    assert result == {}

def test_zip_dicts_overlapping_keys():
    """Test with dictionaries that have all overlapping keys."""
    dict1 = {'a': 1, 'b': 2}
    dict2 = {'a': 10, 'b': 20}
    dict3 = {'a': 100, 'b': 200}

    result = zip_dicts(dict1, dict2, dict3)

    expected = {
        'a': [1, 10, 100],
        'b': [2, 20, 200]
    }
    assert result == expected

def test_zip_dicts_non_dict_input():
    """Test with non-dictionary inputs (should raise TypeError)."""
    with pytest.raises(TypeError):
        zip_dicts({'a': 1}, "not a dict", {'b': 2})

def test_zip_dicts_none_input():
    """Test with None input (should raise TypeError)."""
    with pytest.raises(TypeError):
        zip_dicts({'a': 1}, None, {'b': 2})

def test_zip_dicts_non_hashable_keys():
    """Test with dictionaries containing non-hashable keys."""
    dict1 = {('a', 'b'): 1}  # tuple is hashable
    dict2 = {1: 2}           # int is hashable
    dict3 = {[1, 2]: 3}      # list is not hashable

    with pytest.raises(TypeError):
        zip_dicts(dict1, dict2, dict3)

def test_zip_dicts_special_values():
    """Test with special values like None, 0, False."""
    dict1 = {'a': None, 'b': 0, 'c': False}
    dict2 = {'a': 1, 'd': True}

    result = zip_dicts(dict1, dict2)

    expected = {
        'a': [None, 1],
        'b': [0, None],
        'c': [False, None],
        'd': [None, True]
    }
    assert result == expected
```

### Test Cases Explanation:

1. **Happy Path**: Tests the basic functionality with multiple dictionaries having some overlapping and some unique keys.
2. **Single Dictionary**: Tests the function with just one dictionary.
3. **Empty Dictionaries**: Tests with all empty dictionaries.
4. **Mixed Empty Dictionaries**: Tests with some empty and some non-empty dictionaries.
5. **No Dictionaries**: Tests the function with no arguments.
6. **Overlapping Keys**: Tests with dictionaries that have all keys in common.
